  if n <> 1 then raise exception 'frescor: % · % · % mudou desde a leitura de 03/11', 'faq', 'vale-mais-a-pena-o-estacionamento-oficial-de-congonhas-ou-um', 'pt body_md'; end if;
  total := total + 1;

